KEY_ROLE: Final[Literal["role"]] = "role"
KEY_CONTENT: Final[Literal["content"]] = "content"
KEY_TOOL_CALLS: Final[Literal["tool_calls"]] = "tool_calls"
KEY_TOOL_CALL_ID: Final[Literal["tool_call_id"]] = "tool_call_id"

METADATA_TOOL_CALL_ID: Final = "tool_call_id"
METADATA_TOOL_BATCH_ID: Final = "tool_batch_id"
METADATA_TOOL_SOURCE: Final = "source"
METADATA_TOOL_SOURCE_EXECUTE_STEP: Final = "execute_step"

DEFAULT_MAX_UTTERANCES = 10
# Appended to a bot response the user never heard.
_NOT_HEARD_LABEL: Final = "[Not heard by the user.]"

ToolRunEvent: TypeAlias = ToolExecuted


class LlmMessage(TypedDict, total=False):
    """OpenAI-style chat message for LLM requests.

    ``role`` and ``content`` are present on every message.  Tool turns add the
    native OpenAI fields: an assistant message carrying ``tool_calls`` (content
    may be ``None``), followed by one ``role="tool"`` message per call carrying
    the matching ``tool_call_id``.
    """

    role: str
    content: Optional[str]
    tool_calls: List[Dict[str, Any]]
    tool_call_id: str


def llm_message(role: str, content: Optional[str]) -> LlmMessage:
    """Build one plain (role + content) chat message dict."""
    return {KEY_ROLE: role, KEY_CONTENT: content}


def assistant_tool_calls_message(tool_calls: List[LLMToolCall]) -> LlmMessage:
    """Build an assistant message carrying native ``tool_calls`` (no content).

    Each entry is the OpenAI tool-call shape — ``id``, ``type``, and a
    ``function`` whose ``arguments`` is a JSON **string** — so the ``id`` can be
    paired with the matching tool-result message.

    Runs on the prompt-build path (also during replay from the tracker), so
    ``arguments`` serialization must never raise: non-JSON-serializable values
    go through ``default=str`` with a ``str`` fallback, mirroring
    :func:`_tool_result_content`.
    """
    return {
        KEY_ROLE: ROLE_ASSISTANT,
        KEY_CONTENT: None,
        KEY_TOOL_CALLS: [
            {
                "id": tool_call.id,
                "type": "function",
                "function": {
                    "name": tool_call.tool_name,
                    "arguments": _dump_tool_args(tool_call.tool_args),
                },
            }
            for tool_call in tool_calls
        ],
    }


def _dump_tool_args(tool_args: Any) -> str:
    """JSON-encode tool-call arguments without ever raising.

    Arguments are normally LLM-parsed JSON (already serializable); this guards
    the rare non-serializable value so prompt construction can't crash.
    """
    try:
        return json.dumps(tool_args, default=str)
    except (TypeError, ValueError):
        return str(tool_args)


def tool_result_message(tool_call_id: str, content: str) -> LlmMessage:
    """Build a ``role="tool"`` result message paired to *tool_call_id*."""
    return {KEY_ROLE: ROLE_TOOL, KEY_TOOL_CALL_ID: tool_call_id, KEY_CONTENT: content}


def is_discarded_utterance(event: Event) -> bool:
    """Return whether *event* was marked discarded by a text hook."""
    return (event.metadata or {}).get(DISCARDED_EVENT_METADATA_KEY) is True


def utterance_content(event: Event) -> Optional[str]:
    """Return display text for a user or bot utterance, or None to skip."""
    if is_discarded_utterance(event):
        return None
    if isinstance(event, UserUttered):
        rendered = prompt_text_for_set_memory_utterance(
            event.text or "", event.metadata or {}
        )
        return rendered or None
    if isinstance(event, BotUttered):
        return event.text or None
    return None


def _silence_timeout_content(event: UserSilenceTimeout) -> Optional[str]:
    """Describe a valid recorded silence timeout for the LLM."""
    timeout = event.timeout
    if isinstance(timeout, bool) or not isinstance(timeout, (int, float)):
        return None

    timeout_seconds = float(timeout)
    if not math.isfinite(timeout_seconds) or timeout_seconds <= 0:
        return None

    return f"The user was silent for more than {timeout_seconds:g} seconds."


def is_tool_run_event(event: Event) -> TypeGuard[ToolRunEvent]:
    """Return whether an event records a tool run."""
    return isinstance(event, ToolExecuted)


def serialize_tool_result_value(tool_name: str, value: Any) -> str:
    """Coerce a tool result into the string form stored on the tracker / prompt.

    Serialization must never raise: non-JSON-serializable values (e.g. datetime,
    Decimal, custom types) go through ``default=str``, with a ``str`` fallback
    for anything json still refuses (e.g. circular structures).
    """
    if value is None:
        return f"{tool_name}: done"
    if isinstance(value, str):
        return value
    try:
        return json.dumps(value, default=str)
    except (TypeError, ValueError):
        return str(value)


def _tool_result_content(event: ToolRunEvent) -> str:
    """Return the tool-result string stored at dispatch time.

    Results are normally already normalized to strings at dispatch; this only
    guards the rare non-string payload.
    """
    return serialize_tool_result_value(event.tool_name, event.result)


def _replay_metadata(event: ToolRunEvent) -> Optional[tuple[str, str]]:
    """Return ``(tool_call_id, tool_batch_id)`` when replay metadata is present."""
    metadata = event.metadata or {}
    tool_call_id = metadata.get(METADATA_TOOL_CALL_ID)
    tool_batch_id = metadata.get(METADATA_TOOL_BATCH_ID)
    if not tool_call_id or not tool_batch_id:
        return None
    return str(tool_call_id), str(tool_batch_id)


def _flush_tool_batch(
    batch: List[ToolRunEvent],
    messages: List[LlmMessage],
) -> None:
    """Append assistant tool-call header and tool results for *batch*."""
    if not batch:
        return

    replay_ids = [_replay_metadata(event) for event in batch]
    tool_calls = [
        LLMToolCall(
            id=replay_id[0],
            tool_name=event.tool_name,
            tool_args=dict(event.arguments),
        )
        for event, replay_id in zip(batch, replay_ids)
        if replay_id is not None
    ]
    # Callers only buffer events with replay metadata, so this is normally
    # non-empty; guard anyway so a metadata-less batch can't emit an empty
    # assistant tool-call header.
    if not tool_calls:
        return
    # Append one message with the assistant tool-call header.
    messages.append(assistant_tool_calls_message(tool_calls))

    # Append one message with the tool result for each event in the batch.
    for event, replay_id in zip(batch, replay_ids):
        if replay_id is not None:
            messages.append(
                tool_result_message(replay_id[0], _tool_result_content(event))
            )


def _retained_utterance_window(
    events: List[Event], max_utterances: int
) -> Optional[tuple[int, set[int]]]:
    """Return the tail-walk start index and the ids of the retained utterances.

    History is capped to the last *max_utterances* user/bot utterances. The walk
    normally starts at that window's first retained utterance, but when the cap
    lands on a ``BotUttered`` the start is snapped back to the user message that
    opened its turn: otherwise that turn's tool-run events (which sit
    between the user message and the bot reply) would fall below the start and
    their tool replay would be lost. The snapped-past user text of *older* turns
    stays trimmed (its id is not in the returned set), but when the snapped-to
    message is the current turn's user line (no later user message) it is
    retained so it renders before its own within-turn tool replay instead of
    being appended after it. Returns ``None`` when the tracker holds no
    utterances yet.
    """
    utterance_events = [
        event
        for event in events
        if isinstance(event, (UserUttered, BotUttered))
        and not is_discarded_utterance(event)
    ]
    if not utterance_events:
        return None
    retained_utterances = utterance_events[-max_utterances:]
    retained_utterance_ids = {id(event) for event in retained_utterances}
    start_idx = next(
        i for i, event in enumerate(events) if id(event) == id(retained_utterances[0])
    )
    # Snap back to the turn's opening user message so within-turn tool events are
    # not split off when the window begins on a bot reply.
    for i in range(start_idx, -1, -1):
        if isinstance(events[i], UserUttered):
            start_idx = i
            # If this opening user message is the current turn's (nothing after
            # it is a user message), keep its text so it precedes its own tool
            # replay rather than being tacked on at the tail.
            if not any(isinstance(e, UserUttered) for e in events[i + 1 :]):
                retained_utterance_ids.add(id(events[i]))
            break
    return start_idx, retained_utterance_ids


# TODO (VO-942): Make utterance append outcomes explicit.
# https://rasahq.atlassian.net/browse/VO-942
class _UtteranceAppendOutcome(Enum):
    """The result of rendering one tracker utterance into LLM history."""

    SKIPPED = "skipped"
    APPENDED_USER = "appended_user"
    APPENDED_AGENT = "appended_agent"


class _UtteranceAppendResult(NamedTuple):
    """The result of rendering one tracker utterance into LLM history."""

    outcome: _UtteranceAppendOutcome
    user_text: Optional[str] = None


def _user_event_ids_closed_by_skip_notice(events: List[Event]) -> set[int]:
    """Return ``set:`` taps whose turn ended in the skip notice.

    Those taps did not write. Later history keeps the notice and omits the
    button title, so a refusal is not also a user answer. The notice already
    names the label. An agent line before the notice, such as a session-start
    greeting, does not make the tap an answer.
    """
    # Local import: turn context pulls the model archive, which imports this
    # module while it is still loading.
    from rasa.mantle.orchestration.turn_context import UTTER_ACTION_METADATA_KEY

    hidden: set[int] = set()
    pending_id: Optional[int] = None
    for event in events:
        if isinstance(event, UserUttered):
            pending_id = id(event) if is_set_memory_payload(event.text or "") else None
            continue
        if not isinstance(event, BotUttered) or pending_id is None:
            continue
        action = (event.metadata or {}).get(UTTER_ACTION_METADATA_KEY)
        if action == UTTER_SET_MEMORY_BUTTON_SKIPPED:
            hidden.add(pending_id)
            pending_id = None
    return hidden


def _append_utterance_message(
    event: Event,
    retained_utterance_ids: set[int],
    messages: List[LlmMessage],
    *,
    hidden_user_event_ids: set[int],
    delivery_annotation: Optional[str] = None,
    interrupted_by: Optional[UserBargeIn] = None,
) -> _UtteranceAppendResult:
    """Append an in-window utterance and return the resulting history outcome.

    Utterances older than the window and empty utterances are skipped. The user
    text lets the caller avoid adding the current user turn twice. A barge-in
    that cut this response off replaces its text with the words the user heard.
    """
    if id(event) not in retained_utterance_ids or id(event) in hidden_user_event_ids:
        return _UtteranceAppendResult(_UtteranceAppendOutcome.SKIPPED)
    content = utterance_content(event)
    if content is None:
        return _UtteranceAppendResult(_UtteranceAppendOutcome.SKIPPED)
    if isinstance(event, UserUttered):
        messages.append(llm_message(ROLE_USER, content))
        return _UtteranceAppendResult(_UtteranceAppendOutcome.APPENDED_USER, content)
    if interrupted_by is not None:
        content = format_interrupted_response(content, interrupted_by)
    elif delivery_annotation is not None:
        content = f"{content} {delivery_annotation}"
    messages.append(llm_message(ROLE_ASSISTANT, content))
    return _UtteranceAppendResult(_UtteranceAppendOutcome.APPENDED_AGENT)


class _VoiceDeliveryAnnotations(NamedTuple):
    """Prompt labels for agent responses the user did not fully hear."""

    suffixes: Dict[int, str]
    interrupted_by: Dict[int, UserBargeIn]


def _voice_delivery_annotations(events: List[Event]) -> _VoiceDeliveryAnnotations:
    """Label agent responses the user did not fully hear, keyed by ``id(event)``.

    A ``UserBargeIn`` cuts off the response it names, or the latest response
    since the user last spoke when it names none (native playback reports no
    markers). The cut-off response is rewritten from the barge-in's playback
    markers, including the last word the user heard. Responses saved after the
    cut-off one never played: they waited behind it in the channel, or were
    saved while output was muted.
    """
    suffixes: Dict[int, str] = {}
    interrupted_by: Dict[int, UserBargeIn] = {}
    responses: List[BotUttered] = []
    for event in events:
        if isinstance(event, BotUttered):
            responses.append(event)
            if event.metadata.get(RESPONSE_UNHEARD_METADATA_KEY):
                suffixes[id(event)] = _NOT_HEARD_LABEL
        elif isinstance(event, UserUttered):
            responses = []
        elif isinstance(event, UserBargeIn):
            cut_off = _cut_off_index(event, responses)
            if cut_off is not None:
                response = responses[cut_off]
                interrupted_by[id(response)] = event
                suffixes.pop(id(response), None)
                for later in responses[cut_off + 1 :]:
                    suffixes[id(later)] = _NOT_HEARD_LABEL
                    interrupted_by.pop(id(later), None)
    return _VoiceDeliveryAnnotations(suffixes, interrupted_by)


def _cut_off_index(barge_in: UserBargeIn, responses: List[BotUttered]) -> Optional[int]:
    """Position in *responses* of the one *barge_in* cut off, if it is there."""
    playback = barge_in.metadata.get(BARGE_IN_PLAYBACK_METADATA_KEY) or {}
    response_event_id = playback.get(RESPONSE_EVENT_ID_METADATA_KEY)
    if response_event_id is None:
        return len(responses) - 1 if responses else None
    ids = [response.event_id for response in responses]
    return ids.index(response_event_id) if response_event_id in ids else None


class _ToolBatchAccumulator:
    """Group consecutive tool-run events sharing one ``tool_batch_id``.

    A single LLM response can dispatch several tool calls; they share a batch id
    and must render as one assistant tool-call header plus one tool-result
    message each. Events are buffered until the batch id changes or an utterance
    boundary forces a :meth:`flush`.
    """

    def __init__(self, messages: List[LlmMessage]) -> None:
        self._messages = messages
        self._batch: List[ToolRunEvent] = []
        self._batch_id: Optional[str] = None

    def add(self, event: ToolRunEvent, batch_id: str) -> None:
        """Buffer *event*, flushing first when it starts a new batch."""
        if self._batch and self._batch_id != batch_id:
            self.flush()
        self._batch_id = batch_id
        self._batch.append(event)

    def flush(self) -> None:
        """Render the buffered batch (if any) and reset the buffer."""
        _flush_tool_batch(self._batch, self._messages)
        self._batch = []
        self._batch_id = None


def conversation_messages_from_tracker(
    tracker: Optional[DialogueStateTracker],
    *,
    max_utterances: int = DEFAULT_MAX_UTTERANCES,
) -> tuple[List[LlmMessage], Optional[str]]:
    """Build LLM messages from recent tracker utterances and tool executions.

    Caps history by the last *max_utterances* user/bot utterance events, then
    walks tracker events from that window's first utterance through the tail.
    Tool-run events with replay metadata are grouped by
    ``tool_batch_id`` and emitted as native OpenAI tool-call + tool-result
    pairs. Events missing metadata are skipped.

    Example (two turns, one tool call on turn 1)::

        user: "List my claims"
        assistant: tool_calls=[list_claims]
        tool: '[{"claim_ref": "CLM3101"}]'
        assistant: "I found one claim."
        user: "Tell me more about CLM3101"

    Returns ``(messages, last_user_content)`` for
    :func:`append_current_user_message`.
    """
    if tracker is None:
        return [], None

    events = list(tracker.events)
    delivery = _voice_delivery_annotations(events)
    window = _retained_utterance_window(events, max_utterances)
    if window is None:
        return [], None
    start_idx, retained_utterance_ids = window

    messages: List[LlmMessage] = []
    last_user_content: Optional[str] = None
    tool_batch = _ToolBatchAccumulator(messages)
    hidden_user_event_ids = _user_event_ids_closed_by_skip_notice(events)

    # Walk from the window start through the tail so within-turn tool events
    # (dispatched after the current user message) are included.
    for event in events[start_idx:]:
        if isinstance(event, (UserUttered, BotUttered)):
            # An utterance boundary ends any in-progress tool batch.
            tool_batch.flush()
            append_result = _append_utterance_message(
                event,
                retained_utterance_ids,
                messages,
                hidden_user_event_ids=hidden_user_event_ids,
                delivery_annotation=delivery.suffixes.get(id(event)),
                interrupted_by=delivery.interrupted_by.get(id(event)),
            )
            if append_result.outcome is _UtteranceAppendOutcome.APPENDED_USER:
                last_user_content = append_result.user_text
            continue

        if isinstance(event, UserBargeIn):
            continue

        if isinstance(event, UserSilenceTimeout):
            tool_batch.flush()
            content = _silence_timeout_content(event)
            if content is not None:
                messages.append(llm_message(ROLE_SYSTEM, content))
            continue

        if not is_tool_run_event(event):
            continue
        replay_ids = _replay_metadata(event)
        if replay_ids is not None:
            _, event_batch_id = replay_ids
            tool_batch.add(event, event_batch_id)

    tool_batch.flush()
    return messages, last_user_content


def omit_trailing_user_text(
    messages: List[LlmMessage],
    last_user_content: Optional[str],
    omitted_text: str,
) -> tuple[List[LlmMessage], Optional[str]]:
    """Drop the latest user history line when it equals *omitted_text*.

    Used so text already recorded as ``UserUttered`` but suppressed for this turn
    is not replayed into the prompt. The caller passes the prompt form of that
    turn: plain text unchanged, or the button title for a ``set:`` tap.
    """
    if not omitted_text or last_user_content != omitted_text:
        return messages, last_user_content
    for index in range(len(messages) - 1, -1, -1):
        message = messages[index]
        if message.get(KEY_ROLE) != ROLE_USER:
            continue
        if message.get(KEY_CONTENT) != omitted_text:
            continue
        kept = [*messages[:index], *messages[index + 1 :]]
        new_last: Optional[str] = None
        for prior in reversed(kept):
            if prior.get(KEY_ROLE) != ROLE_USER:
                continue
            content = prior.get(KEY_CONTENT)
            if isinstance(content, str):
                new_last = content
            break
        return kept, new_last
    return messages, last_user_content


def set_memory_button_stored_instruction(memory_key: str) -> str:
    """Return the engine note that a button tap already stored *memory_key*."""
    return (
        f"The button tap already stored `{memory_key}`. "
        f"Do not call `correct` or `set_fields` for `{memory_key}`."
    )


def append_current_user_message(
    messages: List[LlmMessage],
    turn: IncomingTurn,
    last_user_content: Optional[str],
) -> List[LlmMessage]:
    """Append the current user turn when it is not already the last utterance."""
    if turn.suppress_llm_user_message:
        current_user_text = turn.llm_user_message
    else:
        current_user_text = turn.text
    if not current_user_text:
        return messages
    if last_user_content == current_user_text:
        return messages
    return [*messages, llm_message(ROLE_USER, current_user_text)]
